"use client";

import { useEffect, useId, useRef, useState, type FormEvent, type ReactNode, type CSSProperties } from "react";
import Link from "next/link";
import { QRCodeSVG } from "qrcode.react";
import { Alien, ArrowClockwise, ArrowLeft, ArrowRight, Axe, BeerStein, Binoculars, Bird, Bone, BookOpen, Broadcast, Bug, Cards, CardsThree, Check, CheckCircle, Circle, Clock, Compass, Copy, Cow, Crosshair, Crown, CrownCross, Cube, Detective, Dna, Dog, Drop, DropHalf, Eye, EyeClosed, EyeSlash, Fingerprint, Fire, Flask, FlowerLotus, FlyingSaucer, Gauge, Gavel, Gear, Goggles, Hand, HandFist, HandPalm, HandPointing, Heart, HeartBreak, Heartbeat, Hexagon, Hourglass, House, Info, Knife, LockKey, MagicWand, MagnifyingGlass, MaskHappy, MaskSad, Megaphone, Moon, MoonStars, Needle, PawPrint, PersonArmsSpread, PersonSimpleWalk, Planet, QrCode, Robot, Scales, Scan, Scroll, Shield, ShieldChevron, ShieldStar, ShootingStar, Shuffle, SignOut, Skull, Sparkle, SpeakerHigh, SpeakerSlash, Spiral, Star, Student, Sun, SunHorizon, Sunglasses, Swap, Sword, Target, TestTube, Translate, TreasureChest, Users, UsersThree, Wall, Wind, X } from "@phosphor-icons/react";
import { useOneNightRoom, type Language, type Localized, type Role, type Preset, type GameView, type Action, type Command } from "@/lib/oneNightClient";
import { OneNightAudio, type OneNightAudioStatus } from "@/lib/oneNightAudio";
import coreData from "@/public/assets/one-night/core-roles.json";
import expansionData from "@/public/assets/one-night/expansion-roles.json";
import presetData from "@/public/assets/one-night/presets.json";
import avatars from "@/public/assets/werewolf/avatars.json";
import musicTracks from "@/public/assets/werewolf/audio/music.json";
import styles from "./one-night.module.css";
import { RoleLineup } from "@/app/nightfall/RoleLineup";
import { OneNightBotControls, OneNightBotLabel, OneNightBotNotice } from "./OneNightBotControls";

type Collection = { roles: Role[]; presets?: Preset[]; expansions?: { id: string; name: Localized; description?: Localized }[] };
const core = coreData as unknown as Collection;
const extras = expansionData as unknown as Collection;
const roles = [...(Array.isArray(core) ? core : core.roles || []), ...(Array.isArray(extras) ? extras : extras.roles || [])] as Role[];
const roleMap = new Map(roles.map(role => [role.id, role]));
const presets = presetData as Preset[];
const presetPlayers = (preset: Preset) => preset.players ?? preset.roles.length - 3;
const expansions = [...(core.expansions || []), ...(extras.expansions || [])];
const local = (value: Localized | string | null | undefined, lang: Language) => typeof value === "string" ? value : value?.[lang] || "";
const artifactIds=["claw","brand","cudgel","void","mask","shroud","bowOfHunter","cloakOfPrince","swordOfBodyguard","mistOfVampire","alienArtifact","daggerOfTraitor"];
const symbols: Record<string, typeof Moon> = { doppelganger: Fingerprint, werewolf: Moon, minion: MaskSad, mason: Wall, seer: Eye, robber: Hand, troublemaker: Shuffle, drunk: BeerStein, insomniac: Sun, villager: House, tanner: Axe, hunter: Target, sentinel: Shield, alphaWolf: Crown, mysticWolf: Sparkle, apprenticeSeer: Star, paranormalInvestigator: Binoculars, witch: Flask, villageIdiot: Spiral, revealer: SunHorizon, curator: TreasureChest, bodyguard: ShieldChevron, dreamWolf: MoonStars, copycat: Cards, vampire: Drop, master: CrownCross, count: Bone, renfield: Dog, diseased: Bug, cupid: Heart, instigator: Fire, priest: Bird, assassin: Knife, apprenticeAssassin: Sword, marksman: Crosshair, pickpocket: HandPalm, gremlin: MaskHappy, oracle: Compass, alien: Alien, syntheticAlien: Robot, cow: Cow, groob: FlyingSaucer, zerb: Planet, leader: Broadcast, psychic: EyeClosed, rascal: Swap, exposer: Scan, blob: Circle, mortician: Skull, auraSeer: ShootingStar, cursed: Hexagon, prince: PersonArmsSpread, apprenticeTanner: Needle, beholder: EyeSlash, thing: HandPointing, squire: ShieldStar, bodySnatcher: Dna, empath: Heartbeat, nostradamus: Scroll, familyMan: UsersThree, windyWendy: Wind, defenderEr: HandFist, theSponge: DropHalf, ricochetRhino: ArrowClockwise, mirrorMan: Cube, temptress: HeartBreak, drPeeker: Goggles, rapscallion: Sunglasses, henchman: Detective, evilometer: Gauge, madScientist: TestTube, intern: Student, annoyingLad: Megaphone, detector: MagnifyingGlass, roleRetriever: PawPrint, voodooLou: MagicWand, switcheroo: Scales, selfAwarenessGirl: FlowerLotus, flipper: BookOpen, innocentBystander: PersonSimpleWalk };
function RoleSymbol({ id, size = 34 }: { id?: string | null; size?: number }) { const Icon = id ? symbols[id] || CardsThree : CardsThree; if(id && ["werewolf","alphaWolf","mysticWolf","dreamWolf"].includes(id)) return <span className={styles.wolfSymbol} style={{width:size,height:size}} aria-hidden="true"><span/>{id!=="werewolf" && <Icon size={Math.max(12,Math.round(size*.38))} weight="fill"/>}</span>;return <Icon size={size} weight="duotone" aria-hidden="true" />; }
function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const id = useId();
  useEffect(() => { ref.current?.showModal(); }, []);
  return <dialog ref={ref} className={styles.modal} aria-labelledby={id} onCancel={onClose} onClick={event => { if (event.target !== event.currentTarget) return; const box = event.currentTarget.getBoundingClientRect(); if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) onClose(); }}><header className={styles.modalHeader}><h2 id={id}>{title}</h2><button className={styles.iconButton} onClick={onClose} aria-label="Close / 关闭"><X size={23} /></button></header>{children}</dialog>;
}

export default function OneNightApp() {
  const room = useOneNightRoom();
  const view = room.view;
  const [lang, setLang] = useState<Language>("en");
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  const [entry, setEntry] = useState<"join" | "create" | "recover">("join");
  const [name, setName] = useState("");
  const [code, setCode] = useState("");
  const [recovery, setRecovery] = useState("");
  const [modal, setModal] = useState<"invite" | "card" | "rules" | "people" | "audio" | "profile" | "recovery" | "leave" | "disband" | "skip" | "lineup" | "history" | null>(null);
  const [roleInfo, setRoleInfo] = useState<Role | null>(null);
  const [copied, setCopied] = useState(false);
  const [copyFailure, setCopyFailure] = useState(false);
  const [origin, setOrigin] = useState("");
  const [now, setNow] = useState(0);
  const [skipPhase, setSkipPhase] = useState("");
  const [voice, setVoice] = useState(false);
  const [music, setMusic] = useState(false);
  const [track, setTrack] = useState(musicTracks[0].id);
  const [audioStatus, setAudioStatus] = useState<OneNightAudioStatus>("locked");
  const [audioMessage, setAudioMessage] = useState("");
  const audioRef = useRef<OneNightAudio | null>(null);
  const audioHost = useRef(false);
  const audioAck = useRef(room.acknowledgeNightNarration);
  const [lastTimer, setLastTimer] = useState("");
  const me = view?.seats.find(seat => seat.id === view.me?.seatId);
  const currentRole = roleMap.get(view?.me?.originalRoleId || view?.me?.roleId || "");
  const busy = !!room.busy;
  const shareUrl = view ? `${origin}/nightfall/one-night/?room=${view.code}` : "";
  const phaseKind = view?.phase.kind || "lobby";
  const remaining = view?.phase.deadline ? Math.max(0, Math.ceil((view.phase.deadline - now - (view.clockOffset || 0)) / 1000)) : null;

  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      try { if (localStorage.getItem("nightfall.language") === "zh") setLang("zh"); } catch { /* Storage can be unavailable in private browsing. */ }
      setOrigin(window.location.origin); setNow(Date.now());
      const invite = new URLSearchParams(window.location.search).get("room"); if (invite) setCode(invite.toUpperCase());
    });
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => { cancelAnimationFrame(frame); clearInterval(timer); };
  }, []);
  useEffect(() => { audioHost.current = !!view?.isHost; audioAck.current = room.acknowledgeNightNarration; }, [view?.isHost, room.acknowledgeNightNarration]);
  useEffect(() => { const audio = audioRef.current; if (!audio) return; audio.configure({ voice, music, track, language: lang, active: !!view?.me }); if (view?.phase) audio.updatePhase(view.phase); }, [voice, music, track, lang, view?.me, view?.phase]);
  useEffect(() => () => { audioRef.current?.dispose(); }, []);
  useEffect(() => { if (remaining === 0 && view?.phase.kind === "discussion" && lastTimer !== view.phase.id) { audioRef.current?.ringTimer(); const frame = requestAnimationFrame(() => setLastTimer(view.phase.id)); return () => cancelAnimationFrame(frame); } }, [remaining, view?.phase.id, view?.phase.kind, lastTimer]);
  const getAudio = () => { if (!audioRef.current) audioRef.current = new OneNightAudio((status, message) => { setAudioStatus(status); setAudioMessage(message || ""); }, phaseId => { if (audioHost.current) void audioAck.current(phaseId); }); return audioRef.current; };
  const changeAudio = (nextVoice: boolean, nextMusic: boolean) => { setVoice(nextVoice); setMusic(nextMusic); const audio = getAudio(); audio.configure({ voice: nextVoice, music: nextMusic, track, language: lang, active: !!view?.me }); if (view?.phase) audio.updatePhase(view.phase); if (nextVoice || nextMusic) void audio.unlock(); };
  const changeLanguage = () => { const next = lang === "en" ? "zh" : "en"; setLang(next); try { localStorage.setItem("nightfall.language", next); } catch { /* The toggle still works without storage. */ } };
  const copy = async (value: string) => { try { await navigator.clipboard.writeText(value); setCopied(true); setCopyFailure(false); } catch { setCopyFailure(true); } };
  const submitEntry = (event: FormEvent) => { event.preventDefault(); void room.enter(entry, name, code, recovery); };
  const issue = (command: Command) => room.command(command);
  const stageName = () => {
    if (!view) return "";
    if (phaseKind === "ready") return t("Read your card and ready up", "查看身份并准备");
    if (phaseKind === "night") {
      if (!view.phase.roleId) return t("Night is falling", "天黑请闭眼");
      const actingRole = roleTitle(view.phase.roleId, lang);
      return view.phase.nightStage === "opening" ? t(`${actingRole}: open your eyes`, `${actingRole}：请睁眼`) : view.phase.nightStage === "closing" ? t(`${actingRole}: close your eyes`, `${actingRole}：请闭眼`) : t(`Waiting for ${actingRole} to act`, `等待${actingRole}行动`);
    }
    if (phaseKind === "discussion" || phaseKind === "day") return t("Village discussion", "白天讨论");
    if (phaseKind === "voting") return t("Final voting", "最终投票");
    if (view.status === "finished") return t("Game over", "游戏结束");
    return t("Lobby · waiting for players", "大厅 · 等待玩家加入");
  };

  return <div className={styles.app} lang={lang === "zh" ? "zh-Hans" : "en"}>
    <header className={styles.header}><Link href="/nightfall/" className={styles.brand}><ArrowLeft size={19} /><Moon size={23} weight="duotone" /><span>NIGHTFALL<small>{t("ONE NIGHT WEREWOLF", "一夜狼人杀")}</small></span></Link><div className={styles.headerButtons}><button onClick={() => setModal("rules")} className={styles.iconButton} aria-label={t("Rules & role library", "规则与角色库")}><Info size={23} /></button><button onClick={changeLanguage} className={styles.languageButton}><Translate size={18} />{lang === "en" ? "中文" : "English"}</button></div></header>
    {room.error && <div className={styles.error} role="alert"><span>{lang === "zh" ? errorTranslation(room.error.code, room.error.message) : room.error.message}</span><button className={styles.iconButton} onClick={room.clearError} aria-label={t("Dismiss", "关闭")}><X size={19} /></button></div>}
    {room.sessionExpired && <div className={styles.notice}><span>{t("This session has ended. Rejoin to request your seat again.", "当前会话已结束，请重新加入并申请原座位。")}</span><button className={styles.secondary} onClick={() => room.disconnect(true)}>{t("Return to join", "重新加入")}</button></div>}
    {room.session && !room.sessionExpired && room.connectivity !== "online" && <div className={styles.notice} role="status"><span>{t("Reconnecting. Your card and actions are saved.", "正在重新连接。你的身份和操作已保留。")}</span><button className={styles.textButton} onClick={room.retry}>{t("Retry", "重试")}</button></div>}
    {!room.restored || room.session && !view && !room.sessionExpired ? <main className={styles.loading} aria-live="polite"><Moon size={46} weight="duotone" /><h1>{t("Opening the table…", "正在连接牌桌…")}</h1><p>{t("Your private room will appear here.", "即将进入你的私人房间。")}</p></main> : !view ? <main className={styles.entryLayout}>
      <section className={styles.intro}><p className={styles.eyebrow}>{t("EVERYONE PLAYS TO THE REVEAL", "全员参与，直到揭晓")}</p><h1>{t("One night.\nMany secrets.", "一夜之间，\n身份已变。")}</h1><p>{t("Wake up, trade identities, and talk your way to the truth. One vote settles everything.", "夜里行动、交换身份，天亮后用线索与伪装展开讨论。一轮投票，揭晓真相。")}</p><div className={styles.cardFan} aria-hidden="true"><div><Eye size={42} weight="duotone" /></div><div><Moon size={48} weight="duotone" /></div><div><Shuffle size={42} weight="duotone" /></div></div><div className={styles.entryFacts}><span><Users size={19} />{t("Private rooms", "私人房间")}</span><span><CardsThree size={19} />{t("No early elimination", "没有提前出局")}</span><span><SpeakerHigh size={19} />{t("Kokoro narration", "Kokoro 双语法官")}</span></div></section>
      <section className={styles.entryPanel}><div className={styles.tabs}><button className={entry === "join" ? styles.selectedTab : ""} onClick={() => setEntry("join")}>{t("Join a room", "加入房间")}</button><button className={entry === "create" ? styles.selectedTab : ""} onClick={() => setEntry("create")}>{t("Create a room", "创建房间")}</button></div><h2>{entry === "create" ? t("Bring everyone together", "召集你的朋友") : entry === "recover" ? t("Recover the host seat", "恢复房主座位") : t("Take your seat", "请入座")}</h2><p className={styles.muted}>{t("Use a separate phone for each player. Narration can play from one device.", "每位玩家使用自己的手机，任选一台设备播放公共语音。")}</p><form onSubmit={submitEntry} className={styles.form}><label>{t("Your name", "你的名字")}<input value={name} onChange={event => setName(event.target.value)} maxLength={28} required autoComplete="nickname" placeholder={t("What should we call you?", "大家怎么称呼你？")} /></label>{entry !== "create" && <label>{t("Room code", "房间代码")}<input className={styles.roomInput} value={code} onChange={event => setCode(event.target.value.replace(/[^a-zA-Z]/g, "").toUpperCase().slice(0, 4))} maxLength={4} minLength={4} required autoCapitalize="characters" autoCorrect="off" spellCheck={false} placeholder="MOON" /></label>}{entry === "recover" && <label>{t("Host recovery key", "房主恢复密钥")}<input type="password" value={recovery} onChange={event => setRecovery(event.target.value)} required autoComplete="off" /></label>}<button className={styles.primary} disabled={busy}>{busy ? t("Connecting…", "连接中…") : entry === "create" ? t("Create room", "创建房间") : entry === "recover" ? t("Recover room", "恢复房间") : t("Join room", "加入房间")}<ArrowRight size={18} /></button></form><button className={styles.textButton} onClick={() => setEntry(entry === "recover" ? "join" : "recover")}>{entry === "recover" ? t("Back to joining", "返回加入房间") : t("Recover a host seat", "恢复房主座位")}</button></section>
    </main> : <main className={styles.room}>
      {view.me && me && <div className={styles.playerIdentity}><button className={styles.selfPortrait} onClick={() => setModal("profile")} aria-label={t("Change your profile photo", "更换你的头像")}>{avatarGlyph(me.photo, me.name)}</button><div className={styles.selfName}><span>{t(`YOU · SEAT ${me.number}`, `你 · ${me.number}号`)}</span><strong title={me.name}>{me.name}</strong><small>{phaseKind === "ready" ? view.me.ready ? t("Ready for the night", "已准备，等待入夜") : t("Read your card, then ready up", "查看身份，然后准备") : view.status === "lobby" ? t("Your seat at the table", "你在本桌的座位") : view.status === "finished" ? t("Round complete", "本局结束") : t("Everyone stays in until the final vote", "全员参与，直到最终投票")}</small></div>{currentRole && <button className={styles.identityShortcut} onClick={() => setModal("card")}><LockKey size={19}/>{t("My card", "身份牌")}</button>}</div>}
      <StageBanner view={view} lang={lang} title={stageName()}/>
      <div className={styles.roomBar}><button className={styles.codeButton} onClick={() => { setCopied(false); setModal("invite"); }}><span>{t("ROOM", "房间")}</span><strong>{view.code}</strong><Copy size={18} /></button><div className={styles.roomTools}><button className={styles.secondary} onClick={() => { setCopied(false); setModal("invite"); }}><QrCode size={18}/>{t("Invite / QR", "邀请 / 二维码")}</button><button className={styles.iconButton} onClick={() => setModal("audio")} aria-label={t("Narration and music", "语音与音乐")}>{voice || music ? <SpeakerHigh size={23} /> : <SpeakerSlash size={23} />}</button>{view.isHost && <button className={styles.iconButton} onClick={() => setModal("people")} aria-label={t("Manage players", "管理玩家")}><Users size={23} /></button>}<button className={styles.iconButton} onClick={() => setModal("leave")} aria-label={t("Leave room", "离开房间")}><SignOut size={21}/></button></div></div>
      <OneNightBotNotice view={view} lang={lang}/>
      {view.isHost && !!view.requests.length && <div className={styles.notice}><span>{t(`${view.requests.length} player(s) waiting to rejoin.`,`${view.requests.length}位玩家等待接替座位。`)}</span><button className={styles.secondary} onClick={()=>setModal("people")}>{t("Review", "处理申请")}</button></div>}
      {!view.me ? <section className={styles.waiting}><Hourglass size={36} /><h2>{t("Waiting for the host", "等待房主确认")}</h2><p>{t("The game is already underway. The host can give you an open seat or replace your previous connection, keeping its card and history.", "本局已开始。房主可以安排空座或让你接替原座位，保留原身份与行动记录。")}</p></section> : <>
        <div className={styles.playLayout}><section className={styles.tablePanel}><div className={styles.tableToolbar}><button className={styles.secondary} onClick={() => setModal("lineup")}><BookOpen size={18}/>{t("Current roles", "本局角色")}</button>{view.me && view.status !== "lobby" && <button className={styles.secondary} onClick={() => setModal("history")}><Eye size={18}/>{t("My actions", "我的行动")}</button>}<span><Users size={17}/>{t(`${view.seats.length} players`, `${view.seats.length}位玩家`)}</span></div><PlayerTable view={view} lang={lang} remaining={remaining} onProfile={() => setModal("profile")} />
          {!!view.centerCards?.some(card=>card.roleId) && view.status!=="finished" && <div className={styles.publicCenter}><strong>{t("Revealed center cards", "已公开的中央牌")}</strong>{view.centerCards.filter(card=>card.roleId).map(card=><span key={card.id}>{Number(card.id.split(":")[1])+1}. {roleTitle(card.roleId!,lang)}</span>)}</div>}


        </section>
        <aside className={styles.actionColumn}>
          {view.isHost && <div className={styles.hostTools}><OneNightBotControls view={view} lang={lang} disabled={busy || room.connectivity !== "online" || room.sessionExpired} send={issue}/></div>}
          {view.status === "lobby" && (view.isHost ? <DeckSetup view={view} lang={lang} busy={busy} command={issue} onInfo={setRoleInfo} /> : <section className={styles.panel}><h2>{t("The host is setting the table", "房主正在配置牌局")}</h2><p>{t("You can join or leave freely until cards are dealt.", "发牌前可自由加入或离开。")}</p><DeckSummary deck={view.roleDeck} lang={lang} onInfo={setRoleInfo} /></section>)}
          {phaseKind === "ready" && <section className={`${styles.panel} ${styles.readyPanel}`}><button className={view.me.ready ? styles.secondary : styles.primary} onClick={() => setModal("card")}>{view.me.ready ? <CheckCircle size={20}/> : <Eye size={20}/>} {view.me.ready ? t("Read my card again", "再次查看身份") : t("Read card & ready up", "查看身份并准备")}</button><p className={styles.readyStatus}>{view.me.ready ? t("You’re ready. Waiting for the table.", "你已准备，等待其他玩家。") : t("Confirm you’re ready after reading your card.", "查看身份后，请确认准备。")}</p>{view.isHost && <div className={styles.hostReadyAction}><button className={styles.primary} disabled={busy || view.seats.some(seat => !seat.ready || !seat.occupied)} onClick={() => void issue({ type: "startNight" })}>{t("Begin the night", "开始夜晚")}<Moon size={18}/></button></div>}</section>}
          {view.me.action && <NightAction key={`${view.phase.id}:${view.me.action.id}`} action={view.me.action} phaseId={view.phase.id} busy={busy} lang={lang} command={issue} />}
          {phaseKind === "night" && !view.me.action && <section className={`${styles.panel} ${styles.quietPanel}`}><Moon size={40} weight="duotone" /><h2>{t("Keep your secrets", "守住你的秘密")}</h2><p>{t("Wait quietly while the current role acts. Your original role tells you when to wake up, even if your card is moved.", "请安静等待当前角色行动。即使身份被交换，你仍按初始身份行动。")}</p></section>}
          {(phaseKind === "discussion" || phaseKind === "day") && <section className={styles.panel}><h2>{t("What changed overnight?", "昨夜发生了什么？")}</h2><p>{t("Compare clues, ask questions, or bluff. Do not look at your final card before voting.", "对照线索、提问，或大胆伪装。投票前不要查看最终身份。")}</p>{remaining !== null && <p className={styles.timerText}><Clock size={19} />{remaining ? formatTime(remaining) : t("Discussion timer ended", "讨论计时已结束")}</p>}{view.isHost && <button className={styles.primary} disabled={busy} onClick={() => void issue({ type: "startVote" })}>{t("Start voting", "开始投票")}<Gavel size={19} /></button>}</section>}
          {phaseKind === "voting" && <VotePanel view={view} lang={lang} busy={busy} command={issue} />}
          {view.status === "finished" && <section className={styles.panel}><Sun size={38} className={styles.accent} /><h2>{t("Round complete", "本局结束")}</h2><p>{local(view.winner?.text, lang) || t("Compare the final cards and votes below.", "请查看下方最终身份与投票。")}</p>{view.isHost ? <button className={styles.primary} disabled={busy} onClick={() => void issue({ type: "rematch" })}><ArrowClockwise size={18} />{t("Play another round", "再来一局")}</button> : <p>{t("The host can start another round with everyone at the table.", "房主可以保留全桌玩家，再开一局。")}</p>}</section>}
          {view.isHost && view.status === "playing" && phaseKind === "night" && <button className={styles.skipButton} onClick={() => { setSkipPhase(view.phase.id); setModal("skip"); }}>{t("Host: skip current step", "房主：强制跳过当前阶段")}</button>}
          {!!view.me.knowledge?.length && <details className={styles.knowledge} open={phaseKind === "night"}><summary><Eye size={19} />{t("My clues & actions", "我的线索与行动")} <span>{view.me.knowledge.length}</span></summary><ol>{view.me.knowledge.map(item => <li key={item.id}>{local(item.text, lang)}</li>)}</ol></details>}
        </aside></div>
        {!!view.publicRules?.length && <section className={styles.panel}><h2>{t("This round’s public rules", "本局公开规则")}</h2>{view.publicRules.map((rule,index)=><p key={index}>{local(rule,lang)}</p>)}</section>}{view.status === "finished" && <Results view={view} lang={lang} />}
      </>}
    </main>}
    <footer className={styles.footer}><span>{t("One night. Everyone stays in.", "一局一夜，全员参与。")}</span><button className={styles.textButton} onClick={() => setModal("rules")}>{t("Rules, expansions & credits", "规则、扩展与鸣谢")}</button></footer>
    {modal === "invite" && view && <Modal title={t("Bring a friend to the table", "邀请朋友入座")} onClose={() => setModal(null)}><div className={styles.qr}><QRCodeSVG value={shareUrl} size={216} level="M" marginSize={3} /></div><p className={styles.inviteCode}>{view.code}</p><p>{t("Scan this code, or enter the four letters on the join screen. Any player can share this invitation.", "扫描二维码，或在加入页面输入四个字母。任何玩家都可以分享邀请。")}</p><input aria-label={t("Room invitation link", "房间邀请链接")} readOnly value={shareUrl} onFocus={event => event.currentTarget.select()} /><button className={styles.primary} onClick={() => void copy(shareUrl)}><Copy size={18} />{copied ? t("Copied", "已复制") : t("Copy invitation", "复制邀请")}</button>{copyFailure && <p>{t("Select and copy the link above.", "请选中并复制上方链接。")}</p>}</Modal>}
    {modal === "lineup" && view && <Modal title={t("Current roles", "本局角色")} onClose={() => setModal(null)}><RoleLineup deck={view.roleDeck} roles={roles} lang={lang} renderIcon={id => <RoleSymbol id={id} size={28}/>} variant="one-night" extraCards={view.roleDeck.includes("alphaWolf") ? ["werewolf"] : []}/></Modal>}
    {modal === "history" && view?.me && <Modal title={t("My actions & results", "我的行动与结果")} onClose={() => setModal(null)}><p>{t("Only you can see these clues. They follow your seat when you reconnect.", "仅你可以查看这些线索，重连后仍随座位保留。")}</p>{view.me.knowledge.length ? <ol className={styles.historyList}>{view.me.knowledge.map(item => <li key={item.id}>{local(item.text, lang)}</li>)}</ol> : <p className={styles.muted}>{t("Your private actions and results will appear here.", "你的秘密行动及结果将在此显示。")}</p>}</Modal>}
    {modal === "card" && view?.me && <Modal title={t("Your starting card", "你的初始身份")} onClose={() => setModal(null)}><div className={styles.roleCard}><RoleSymbol id={currentRole?.id} size={82} /><h2>{local(currentRole?.name, lang) || t("Card not dealt", "尚未发牌")}</h2><span>{teamName(currentRole?.team, lang)}</span></div><p>{local(currentRole?.description, lang)}</p><p className={styles.muted}>{t("This is the card you received. It is not a live view of swaps made during the night.", "这是发牌时的身份，不会显示夜间交换后的最终身份。")}</p>{phaseKind === "ready" && !view.me.ready ? <button className={styles.primary} disabled={busy} onClick={async () => { if (await issue({ type: "ready" })) setModal(null); }}><CheckCircle size={20} />{t("I’ve read my card. Ready!", "我已读完身份，准备好了！")}</button> : <button className={styles.secondary} onClick={() => setModal(null)}><EyeSlash size={18} />{t("Hide card", "收起身份卡")}</button>}</Modal>}
    {modal === "audio" && <Modal title={t("Narration & music", "语音与音乐")} onClose={() => setModal(null)}><p>{t("Enable on one device for the whole table. Male Kokoro voices narrate in your selected language.", "建议全桌仅在一台设备开启语音。Kokoro 男声会使用你选择的语言主持。")}</p><label className={styles.toggle}><span>{t("Voice moderator", "语音法官")}</span><input type="checkbox" checked={voice} onChange={event => changeAudio(event.target.checked, music)} /></label><label className={styles.toggle}><span>{t("Background music", "背景音乐")}</span><input type="checkbox" checked={music} onChange={event => changeAudio(voice, event.target.checked)} /></label><label>{t("Ambience", "背景曲目")}<select value={track} onChange={event => setTrack(event.target.value)}>{musicTracks.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><div className={styles.buttonRow}><button className={styles.secondary} onClick={() => { const audio = getAudio(); audio.configure({ voice, music, track, language: lang, active: !!view?.me }); void audio.testSound(); }}>{t("Test sound", "测试声音")}</button><button className={styles.secondary} onClick={() => { const audio = getAudio(); void audio.unlock(); }}>{t("Enable sound", "开启声音")}</button><button className={styles.textButton} onClick={() => audioRef.current?.replay()}>{t("Replay prompt", "重播提示")}</button></div><p className={styles.muted} role="status">{audioMessage || (audioStatus === "locked" ? t("Tap Enable sound before starting. On iPhone, keep this page open during narration.", "开始前请点击开启声音。在 iPhone 上播放时请保持此页面打开。") : t("Sound is enabled on this device.", "此设备的声音已开启。"))}</p></Modal>}
    {modal === "people" && view && <Modal title={t("Manage the table", "管理牌桌")} onClose={() => setModal(null)}><People view={view} lang={lang} busy={busy} command={issue} /><button className={styles.secondary} onClick={() => setModal("recovery")}>{t("Host recovery key", "房主恢复密钥")}</button><button className={styles.danger} onClick={() => setModal("disband")}>{t("Disband room", "解散房间")}</button></Modal>}
    {modal === "profile" && view?.me && <Modal title={t("Choose your profile photo", "选择你的头像")} onClose={() => setModal(null)}><div className={styles.avatarGrid}>{avatars.map(avatar => <button key={avatar.id} disabled={busy} className={me?.photo === avatar.id ? styles.selectedAvatar : ""} aria-label={avatar.name[lang]} title={avatar.name[lang]} onClick={async () => { if (await issue({ type: "updateProfile", photo: avatar.id })) setModal(null); }}>{avatar.glyph}</button>)}</div></Modal>}
    {modal === "recovery" && <Modal title={t("Keep this key private", "请保管好恢复密钥")} onClose={() => setModal(null)}><p>{t("If the host changes devices, use this key to recover the host seat. Anyone with it can take control of the room.", "房主更换设备后，可用此密钥恢复房主座位。持有密钥的人能控制房间，请勿分享。")}</p><input readOnly value={room.session?.recoveryKey || ""} onFocus={event => event.currentTarget.select()} aria-label={t("Host recovery key", "房主恢复密钥")} /><button className={styles.primary} onClick={() => void copy(room.session?.recoveryKey || "")}>{copied ? t("Copied", "已复制") : t("Copy key", "复制密钥")}</button></Modal>}
    {modal === "leave" && <Modal title={t("Leave this table?", "离开牌桌？")} onClose={() => setModal(null)}><p>{view?.isHost ? t("Transfer host control to another player, or disband the room for everyone.", "请先将房主转交另一位玩家，或解散全桌房间。") : view?.status === "lobby" ? t("Your seat becomes available. You can join again with the room code.", "你的座位将空出，之后可用房间代码重新加入。") : t("Your seat and card remain. Rejoin on this device to return, or ask the host to approve a replacement on another device.", "座位和身份会保留。在此设备重新加入即可返回，换设备时需要房主确认接替。")}</p>{view?.isHost ? <div className={styles.buttonRow}><button className={styles.secondary} onClick={()=>setModal("people")}>{t("Manage players", "管理玩家")}</button><button className={styles.danger} onClick={()=>setModal("disband")}>{t("Disband room", "解散房间")}</button></div> : <button className={styles.primary} disabled={busy} onClick={async () => { if (view?.me && view.status !== "lobby") { room.disconnect(); setModal(null); } else if (await issue({ type: "leave" })) { room.disconnect(true); setModal(null); } }}>{t("Leave room", "离开房间")}</button>}</Modal>}
    {modal === "disband" && <Modal title={t("Disband this room?", "解散这个房间？")} onClose={() => setModal(null)}><p>{t("This ends the room for everyone. All players will return to the join screen.", "所有玩家都会离开房间并返回加入页面。")}</p><button className={styles.danger} disabled={busy} onClick={async () => { if (await issue({ type: "disbandRoom" })) setModal(null); }}>{t("Disband for everyone", "确认解散房间")}</button></Modal>}
    {modal === "skip" && <Modal title={t("Skip the current step?", "跳过当前阶段？")} onClose={() => setModal(null)}><p>{t("Use this only when the table agrees. Unfinished actions will be skipped. No private roles or acting players are shown to the host.", "请先征得全桌同意。未完成的行动将跳过，房主不会看到玩家的隐藏身份或谁在行动。")}</p><button className={styles.danger} disabled={busy || view?.phase.id !== skipPhase} onClick={async () => { if (await issue({ type: "hardSkip", expectedPhaseId: skipPhase })) setModal(null); }}>{view?.phase.id !== skipPhase ? t("The stage has already changed", "阶段已变化") : t("Skip this step", "跳过此阶段")}</button></Modal>}
    {modal === "rules" && <Modal title={t("Before night falls", "天黑之前")} onClose={() => setModal(null)}><div className={styles.rules}><p>{t("Deal one secret card to each player and leave three in the center. Follow your starting role when the narrator calls it, even if your card is later moved.", "每人领取一张秘密身份牌，中央放三张牌。夜间按初始身份听取提示并行动，即使你的牌后来被交换。")}</p><p>{t("At dawn, discuss what happened. Everyone votes for another player. Final identities and expansion effects determine who wins; no one is eliminated before the final vote.", "天亮后讨论昨夜发生的事。所有人投票给另一位玩家。最终身份及扩展效果决定胜负，最终投票前没有人出局。")}</p><p>{t("Normally, every player tied for the most votes is eliminated if that total is at least two. If everyone receives at most one vote, nobody is eliminated. Some roles and marks change this resolution.", "通常最高票达到两票时，所有并列最高票玩家均出局；若每人最多一票，则无人出局。部分角色和标记会改变结算。")}</p><p>{t("Actions do not expire when a player disconnects. Reconnect to keep your card, or let the host approve your replacement. The host can skip a stalled step without seeing anyone’s secret role.", "断线不会自动跳过行动。重新连接可保留身份，或由房主确认新设备接替。房主可强制跳过卡住的阶段，但不能查看他人的身份。")}</p><p>{t("Includes the original game, Daybreak, Vampire, Alien, Bonus Packs, and Super Villains. Alien uses a published-rule adaptation; it does not reproduce the companion app’s complete random-event catalogue.","包括基础版、破晓、吸血鬼、外星人、奖励包和超级反派。外星人采用公开规则改编，并未复刻官方配套应用的完整随机事件库。")}</p><h3>{t("Role library", "角色库")}</h3><div className={styles.roleLibrary}>{roles.map(role => <button className={styles.roleLibraryRow} key={role.id} onClick={() => setRoleInfo(role)}><RoleSymbol id={role.id} size={25} /><span>{local(role.name, lang)}</span><Info size={18} /></button>)}</div><h3>{t("Narration & music", "语音与音乐")}</h3><p>{t("Narration is generated locally with Kokoro: Michael in English and zm_010 in Mandarin. Kokoro model licenses: Apache 2.0.", "语音由本地 Kokoro 生成：英语为 Michael，普通话为 zm_010，模型采用 Apache 2.0 许可。")}</p><p><a href="/assets/one-night/audio/" target="_blank" rel="noreferrer">{t("Listen to the One Night recordings", "试听一夜狼人杀语音")}</a></p><p>{t("Music by Kevin MacLeod, licensed under ", "背景音乐由 Kevin MacLeod 创作，采用 ")}<a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.<br />{musicTracks.map((item, i) => <span key={item.id}>{i ? " · " : ""}<a href={item.source} target="_blank" rel="noreferrer">{item.title}</a></span>)}</p><p><a href="https://beziergames.com/pages/rules" target="_blank" rel="noreferrer">{t("Official Bézier Games rulebooks", "Bézier Games 官方规则书")}</a></p><p><a href="https://game-icons.net/1x1/lorc/wolf-head.html" target="_blank" rel="noreferrer">{t("Wolf head by Lorc", "狼头图标：Lorc")}</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noreferrer">CC BY 3.0</a></p><p className={styles.muted}>{t("An independent fan implementation, not affiliated with Bézier Games.", "本项目为独立爱好者实现，与 Bézier Games 无关联。")}</p></div></Modal>}
    {roleInfo && <Modal title={local(roleInfo.name, lang)} onClose={() => setRoleInfo(null)}><div className={styles.roleCard}><RoleSymbol id={roleInfo.id} size={72} /><span>{teamName(roleInfo.team, lang)}</span></div><p>{local(roleInfo.description, lang)}</p></Modal>}
  </div>;
}

function roleTitle(id:string,lang:Language):string{const special:Record<string,Localized>={markReview:{en:"Check your mark",zh:"查看标记"},lovers:{en:"Lovers",zh:"情侣相认"},villains:{en:"Villains",zh:"反派相认"}}; if(special[id])return special[id][lang];if(id.startsWith("doppel:"))return `${lang==="en"?"Doppelgänger · ":"化身幽灵 · "}${roleTitle(id.slice(7),lang)}`;return local(roleMap.get(id)?.name,lang)||id;}
function seatLabel(view: GameView, id: string) { const seat = view.seats.find(item => item.id === id); return seat ? `${seat.number}. ${seat.name}` : id; }
function avatarGlyph(photo?: string | null, name?: string) { return avatars.find(item => item.id === photo)?.glyph || name?.trim().slice(0, 1).toUpperCase() || "?"; }
function formatTime(seconds: number) { return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`; }
function teamName(team: string | undefined, lang: Language) { const teams: Record<string, Localized> = { village: {en:"Village",zh:"村庄阵营"}, villager:{en:"Village",zh:"村庄阵营"}, wolf:{en:"Werewolves",zh:"狼人阵营"}, werewolf:{en:"Werewolves",zh:"狼人阵营"}, vampire:{en:"Vampires",zh:"吸血鬼阵营"}, alien:{en:"Aliens",zh:"外星人阵营"}, tanner:{en:"Tanner",zh:"皮匠阵营"}, neutral:{en:"Personal objective",zh:"独立目标"}, superhero:{en:"Heroes",zh:"英雄阵营"}, villain:{en:"Villains",zh:"反派阵营"} }; return teams[team || ""]?.[lang] || team || ""; }
function errorTranslation(code: string, fallback: string) { const translations: Record<string, string> = { "bot-idle":"当前没有机器人需要行动。请完成真人行动，或使用房主控制推进。", "invalid-bot-count":"请选择有效的机器人数量，房间最多16个座位。", "invalid-bot-mode":"请选择自动或手动模式。", "bot-host":"机器人不能成为房主。", "connection":"无法连接游戏服务，正在重试。你的身份与操作已保留。", "room-disbanded":"房主已解散房间。", "room-not-found":"找不到这个房间，可能已结束或过期。", "room-expired":"房间已过期，请创建或加入新房间。", "invalid-recovery-key":"房主恢复密钥不正确。", "too-many-requests":"操作过于频繁，请稍后重试。", "not-host":"只有房主能执行此操作。", "not-ready":"请等待所有玩家查看身份并准备。", "invalid-room-code":"请输入四个英文字母的房间代码。", "stale-phase":"阶段已变化，请根据最新提示操作。", "host-only":"只有房主可以执行此操作。", "wrong-phase":"当前阶段不可执行此操作。", "invalid-target":"请选择有效的行动目标。", "invalid-deck":"身份牌需比玩家人数多三张，且不能超过各角色数量上限。工匠必须成对使用。", "empty-seats":"所有座位都需要有人加入，才能发牌。", "pending-votes":"请等待所有玩家完成投票。", "self-vote":"请投给另一位玩家，不能投自己。", "not-seated":"你的座位已被替换或移除，请重新加入。", "invalid-choice":"请选择有效的行动选项。", "room-full":"房间已满。", "invalid-settings":"请设置1至30分钟的讨论时间。" }; return translations[code.toLowerCase().replaceAll("_","-")] || fallback; }

function StageBanner({view,lang,title}:{view:GameView;lang:Language;title:string}) {
  const t=(en:string,zh:string)=>lang==="en"?en:zh;
  const ready=view.phase.kind==="ready", voting=view.phase.kind==="voting";
  const waiting=ready?view.seats.filter(seat=>!seat.ready||!seat.occupied):voting?view.seats.filter(seat=>view.pendingVoterIds?.includes(seat.id)):[];
  const phaseLabel=view.phase.kind==="night"?t("Night","夜晚"):["discussion","day","voting"].includes(view.phase.kind)?t("Day","白天"):t("Your table","当前牌局");
  return <section className={styles.stageBanner}>
    <div className={styles.stageLine} role="status" aria-live="polite"><span>{phaseLabel}</span><h1>{title}</h1>{(ready||voting)&&<span className={styles.stageCount}>{view.seats.length-waiting.length} / {view.seats.length}<small>{ready?t("ready","已准备"):t("voted","已投票")}</small></span>}</div>
    {(ready||voting)&&(waiting.length?<details className={styles.pendingDisclosure}><summary><span>{ready?t("Waiting for","等待准备"):t("Still to vote","等待投票")}</span><span className={styles.pendingSeatNumbers}>{waiting.map(seat=><b key={seat.id} title={seat.name}>{seat.number}</b>)}</span></summary><ul>{waiting.map(seat=><li key={seat.id}><b>{seat.number}</b><span>{seat.name}</span>{!seat.connected&&!seat.isBot&&<small>{t("offline","离线")}</small>}</li>)}</ul></details>:<p className={styles.allDecisionsDone} role="status">{ready?t("Everyone is ready · the host can begin","全员已准备，房主可以开始"):t("Everyone has voted · the host can reveal","全员已投票，房主可以揭晓结果")}</p>)}
    {view.me?.action&&<p className={styles.currentAction}>{t("Your turn. Make your private choice below.","轮到你了，请在下方秘密行动。")}</p>}
  </section>;
}

function PlayerTable({view, lang, remaining, onProfile}: {view: GameView; lang: Language; remaining: number | null; onProfile: () => void}) {
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  const large=view.seats.length>6, rows=Math.ceil(view.seats.length/2);
  return <div className={styles.tableScroll}><div className={`${styles.table} ${large?styles.largeTable:""}`} style={large?{"--seat-rows":rows} as CSSProperties:undefined} aria-label={t("Players seated clockwise", "玩家按顺时针入座")}>
    <div className={styles.tableRing}/>
    <div className={styles.tableCenter}>{remaining!==null&&(view.phase.kind==="discussion"||view.phase.kind==="day")?<><Hourglass size={29} weight={remaining?"duotone":"fill"}/><strong>{formatTime(remaining)}</strong><span>{t("Discussion","讨论时间")}</span></>:<><span className={styles.centerLabel}>{t("CENTER","中央牌")}</span><div className={styles.centerCards}>{Array.from({length:view.centerCount||3},(_,index)=>index).map(index=><span key={index} title={view.centerCards?.[index]?.roleId?roleTitle(view.centerCards[index].roleId!,lang):undefined}><RoleSymbol id={view.centerCards?.[index]?.roleId} size={20}/><small>{index+1}</small></span>)}</div></>}{large&&<span className={styles.clockwiseLabel}><ArrowClockwise size={16}/>{t("Clockwise","顺时针")}</span>}</div>
    {view.seats.map((seat,index)=>{
      const angle=-Math.PI/2+2*Math.PI*index/Math.max(1,view.seats.length), mine=seat.id===view.me?.seatId;
      const pending=view.phase.kind==="ready"?!seat.ready:view.phase.kind==="voting"?!!view.pendingVoterIds?.includes(seat.id):false;
      const status=seat.revealedRoleId?roleTitle(seat.revealedRoleId,lang):view.phase.kind==="ready"?seat.ready?t("Ready","已准备"):t("Not ready","未准备"):view.phase.kind==="voting"?pending?t("To vote","未投票"):t("Voted","已投票"):!seat.occupied?t("Reserved","预留"):seat.isBot?t("Bot","机器人"):!seat.connected?t("Offline","离线"):mine?t("You","你"):"";
      const position=large?{gridColumn:index<rows?3:1,gridRow:index<rows?index+1:view.seats.length-index}:{left:`${50+37*Math.cos(angle)}%`,top:`${50+37*Math.sin(angle)}%`};
      return <div key={seat.id} className={`${styles.seat} ${mine?styles.ownSeat:""} ${!seat.connected&&!seat.isBot?styles.offlineSeat:""} ${pending?styles.seatPending:""}`} style={position}>
        <div className={styles.seatPortrait}><button onClick={mine?onProfile:undefined} disabled={!mine} className={styles.seatAvatar} aria-label={`${seat.number}. ${seat.name}${seat.isBot?t(", test bot","，测试机器人"):""}${mine?t(", your profile","，你的头像"):""}`}><span>{avatarGlyph(seat.photo, seat.name)}</span><b>{seat.number}</b>{(seat.host||seat.isHost||seat.id===view.hostSeatId)&&<Crown size={15} className={styles.hostCrown} weight="fill"/>}</button>{seat.isBot&&<OneNightBotLabel lang={lang} overlay/>}{(seat.shielded||seat.hasArtifact)&&<span className={styles.seatTokens}>{seat.shielded&&<span role="img" aria-label={t(`Seat ${seat.number}: shielded card`,`${seat.number}号：身份牌有护盾`)} title={t("Shielded card","身份牌有护盾")}><Shield size={15} weight="fill" aria-hidden="true"/></span>}{seat.hasArtifact&&<span role="img" aria-label={t(`Seat ${seat.number}: has a private artifact`,`${seat.number}号：持有秘密神器`)} title={t("Artifact present; identity is private","持有神器，具体种类保密")}><TreasureChest size={15} weight="duotone" aria-hidden="true"/></span>}</span>}</div>
        <div className={styles.seatText}><strong title={seat.name}>{seat.name}</strong><small>{status}</small></div>
      </div>;
    })}
  </div></div>;
}

function DeckSummary({deck,lang,onInfo}:{deck:string[];lang:Language;onInfo:(role:Role)=>void}) { const counts = countDeck(deck); return <div className={styles.deckSummary}>{Object.entries(counts).map(([id,count]) => <button key={id} onClick={() => { const role = roleMap.get(id); if (role) onInfo(role); }}><RoleSymbol id={id} size={20}/><span>{local(roleMap.get(id)?.name,lang) || id}</span><b>×{count}</b></button>)}</div>; }
function countDeck(deck: string[]) { return deck.reduce<Record<string,number>>((counts,id) => {counts[id]=(counts[id]||0)+1;return counts;},{}); }

function DeckSetup({view,lang,busy,command,onInfo}:{view:GameView;lang:Language;busy:boolean;command:(cmd:Command)=>Promise<boolean>;onInfo:(role:Role)=>void}) {
  const t=(en:string,zh:string)=>lang==="en"?en:zh;
  const [editing,setEditing]=useState(view.roleDeck.length===0);
  const [deck,setDeck]=useState(view.roleDeck);
  const [seconds,setSeconds]=useState(Number(view.settings.discussionSeconds||300));
  const [loneWolf,setLoneWolf]=useState(view.settings.loneWolf!==false);
  const [selectedPreset,setSelectedPreset]=useState("");
  const [alienVariant,setAlienVariant]=useState(String(view.settings.alienVariant||"random"));
  const [artifacts,setArtifacts]=useState<string[]>(Array.isArray(view.settings.artifacts)?view.settings.artifacts as string[]:artifactIds);
  const [filter,setFilter]=useState("selected");
  const [search,setSearch]=useState("");
  const counts=countDeck(deck), needed=view.seats.length+3;
  const selected=presets.find(item=>item.id===selectedPreset);
  const presetSizes=[...new Set(presets.map(presetPlayers))].sort((a,b)=>Number(b===view.seats.length)-Number(a===view.seats.length)||a-b);
  const groups=[...new Set(roles.map(role=>role.expansion||"base"))];
  const query=search.trim().toLocaleLowerCase();
  const visibleRoles=roles.filter(role=>query?`${role.name.en} ${role.name.zh}`.toLocaleLowerCase().includes(query):filter==="selected"?!!counts[role.id]:role.expansion===filter);
  const change=(role:Role,amount:number)=>{setSelectedPreset("");setDeck(old=>amount>0?[...old,role.id]:old.filter((id,index)=>id!==role.id||index!==old.indexOf(role.id)));};
  const beginEdit=()=>{setDeck(view.roleDeck);setFilter("selected");setSearch("");setEditing(true);};
  const save=async()=>{if(await command({type:"configure",roleDeck:deck,settings:{...view.settings,discussionSeconds:seconds,loneWolf,alienVariant,artifacts}}))setEditing(false);};
  const shortage=needed-deck.length;
  return <section className={`${styles.panel} ${styles.setupPanel}`}>
    <div className={styles.sectionHeader}><div><h2>{t("Set the table","配置牌局")}</h2><p className={styles.setupSummary}>{t(`${view.seats.length} players + 3 center cards`,`${view.seats.length}位玩家 + 3张中央牌`)}</p></div>{!editing&&<button className={styles.iconButton} onClick={beginEdit} aria-label={t("Edit deck","编辑牌组")}><Gear size={22}/></button>}</div>
    {!editing?<>
      <DeckSummary deck={view.roleDeck} lang={lang} onInfo={onInfo}/>
      {view.roleDeck.length!==needed&&<p className={styles.warning}>{t(`${view.roleDeck.length} cards selected; ${needed} needed.`,`已选${view.roleDeck.length}张，需要${needed}张。`)}</p>}
      <button className={styles.secondary} onClick={beginEdit}>{t("Edit roles & settings","编辑角色与设置")}</button>
      <button className={styles.primary} disabled={busy||view.seats.length<3||view.seats.some(seat=>!seat.occupied)||view.roleDeck.length!==needed} onClick={()=>void command({type:"start"})}>{t("Deal secret cards","发放身份牌")}<CardsThree size={19}/></button>
    </>:<>
      <div className={styles.deckToolbar}><div aria-live="polite"><strong>{deck.length}<span> / {needed}</span></strong><small>{shortage===0?t("Deck ready","牌组已齐"):shortage>0?t(`Add ${shortage} cards`,`还需${shortage}张`):t(`Remove ${-shortage} cards`,`请减少${-shortage}张`)}</small></div><button className={styles.primary} disabled={busy} onClick={()=>void save()}>{busy?t("Saving…","保存中…"):t("Save deck","保存牌组")}</button><button className={styles.iconButton} onClick={()=>setEditing(false)} aria-label={t("Cancel deck changes","取消牌组修改")}><X size={21}/></button></div>
      <label className={styles.presetLabel}>{t("Start with a preset","从预设开始")}<select value={selectedPreset} onChange={event=>{const preset=presets.find(item=>item.id===event.target.value);setSelectedPreset(event.target.value);if(preset){setDeck(preset.roles||preset.roleDeck||[]);setFilter("selected");setSearch("");}}}><option value="">{t("Choose a preset, or build your own","选择预设，或自行配置")}</option>{presetSizes.map(size=><optgroup key={size} label={t(`${size} players${size===view.seats.length?" · your table":""}`,`${size}人${size===view.seats.length?" · 当前人数":""}`)}>{presets.filter(preset=>presetPlayers(preset)===size).map(preset=><option key={preset.id} value={preset.id}>{local(preset.name,lang)}</option>)}</optgroup>)}</select></label>
      {selected&&<p className={styles.presetDescription}>{local(selected.description,lang)}{presetPlayers(selected)!==view.seats.length&&<strong>{t(`For ${presetPlayers(selected)} players; ${view.seats.length} seated.`,`适合${presetPlayers(selected)}人，当前${view.seats.length}人。`)}</strong>}</p>}
      <div className={styles.roleBrowserControls}><label>{t("Browse roles","浏览角色")}<select value={filter} onChange={event=>{setFilter(event.target.value);setSearch("");}}><option value="selected">{t(`In this deck (${deck.length})`,`本局牌组（${deck.length}）`)}</option>{groups.map(group=><option value={group} key={group}>{local(expansions.find(item=>item.id===group)?.name,lang)||expansionName(group,lang)}</option>)}</select></label><label className={styles.roleSearch}><span>{t("Find a role","查找角色")}</span><input value={search} onChange={event=>setSearch(event.target.value)} placeholder={t("Name in English or Chinese","输入中文或英文名称")} type="search"/></label></div>
      {filter==="alien"&&<p className={styles.scopeNote}>{t("Published-rule adaptation; the official app’s full random-event catalogue is not included.","采用公开规则改编，不含官方应用的完整随机事件库。")}</p>}
      <div className={styles.roleBrowser} aria-label={t("Role quantities","角色数量")}>
        {!visibleRoles.length?<div className={styles.emptyDeck}><CardsThree size={29}/><p>{query?t("No matching role. Try another name.","没有匹配的角色，请换个名称。"):t("Choose a preset above, or browse an expansion to add roles.","先选择预设，或切换扩展添加角色。")}</p>{!query&&<button className={styles.secondary} onClick={()=>setFilter("base")}>{t("Browse original roles","浏览基础角色")}</button>}</div>:visibleRoles.map(role=><div className={styles.roleRow} key={role.id}><RoleSymbol id={role.id} size={24}/><button className={styles.roleNameButton} onClick={()=>onInfo(role)} aria-label={`${t("About","关于")} ${local(role.name,lang)}`}><span>{local(role.name,lang)}</span><Info size={17}/></button><div className={styles.counter}><button disabled={busy||!counts[role.id]} onClick={()=>change(role,-1)} aria-label={`${t("Remove","减少")} ${local(role.name,lang)}`}>−</button><strong>{counts[role.id]||0}</strong><button disabled={busy||(counts[role.id]||0)>=(role.maxCount||1)||deck.length>=19} onClick={()=>change(role,1)} aria-label={`${t("Add","添加")} ${local(role.name,lang)}`}>+</button></div></div>)}
      </div>
      <details className={styles.advancedSettings}><summary><Gear size={18}/>{t("Timer & advanced rules","计时与进阶规则")}</summary><div>
        <label>{t("Discussion timer","讨论计时")}<select value={seconds} onChange={event=>setSeconds(Number(event.target.value))}>{[60,120,180,300,480,600,900,1200,1800].map(value=><option key={value} value={value}>{value/60} {t("minutes","分钟")}</option>)}</select></label>
        <label className={styles.toggle}><span>{t("A lone wolf may view one center card","独狼可查看一张中央牌")}</span><input type="checkbox" checked={loneWolf} onChange={event=>setLoneWolf(event.target.checked)}/></label>
        {roles.some(role=>role.expansion==="alien"&&counts[role.id])&&<label>{t("Alien night instruction","外星人夜间规则")}<select value={alienVariant} onChange={event=>setAlienVariant(event.target.value)}><option value="random">{t("Random published variant","随机公开规则变体")}</option><option value="recognize">{t("Recognize teammates","辨认同伴")}</option><option value="center">{t("Recognize & inspect a center card","辨认同伴并查看中央牌")}</option><option value="convert">{t("Recognize & convert one player","辨认同伴并转化一位玩家")}</option></select></label>}
        {!!counts.curator&&<details className={styles.artifactSettings}><summary>{t("Curator artifacts","馆长神器池")} ({artifacts.length})</summary>{artifactIds.map(id=><label className={styles.toggle} key={id}><span>{tokenName(id,lang)}</span><input type="checkbox" checked={artifacts.includes(id)} disabled={artifacts.length===1&&artifacts.includes(id)} onChange={()=>setArtifacts(old=>old.includes(id)?old.filter(value=>value!==id):[...old,id])}/></label>)}</details>}
      </div></details>
    </>}
  </section>;
}

function expansionName(id:string,lang:Language){const names:Record<string,Localized>={base:{en:"Original Werewolf",zh:"基础版"},daybreak:{en:"Daybreak",zh:"破晓"},vampire:{en:"Vampire",zh:"吸血鬼"},alien:{en:"Alien",zh:"外星人"},superVillains:{en:"Super Villains",zh:"超级反派"},bonus:{en:"Bonus roles",zh:"奖励角色"},bonus1:{en:"Bonus Pack 1",zh:"奖励包1"},bonus2:{en:"Bonus Pack 2",zh:"奖励包2"},bonus3:{en:"Bonus Pack 3",zh:"奖励包3"},bonus4:{en:"Bonus Pack 4",zh:"奖励包4"}};return names[id]?.[lang]||id;}

function NightAction({action,phaseId,busy,lang,command}:{action:Action;phaseId:string;busy:boolean;lang:Language;command:(cmd:Command)=>Promise<boolean>}) {
  const t=(en:string,zh:string)=>lang==="en"?en:zh;
  const [targets,setTargets]=useState<string[]>([]);
  const [choice,setChoice]=useState(action.options?.length===1?action.options[0].id:"");
  const toggle=(id:string)=>setTargets(old=>old.includes(id)?old.filter(value=>value!==id):action.max===1?[id]:old.length<action.max?[...old,id]:old);
  const valid=targets.length>=action.min&&targets.length<=action.max&&(!action.options?.length||!!choice)&&(action.roleId!=="nostradamus"||(choice==="inspect"?targets.length===1:choice==="finish"?targets.length===0:true));
  const submit=(skip=false)=>command({type:"act",expectedPhaseId:phaseId,actionId:action.id,targets:skip?[]:targets,choice:skip?"skip":choice||undefined,skip});
  return <section className={`${styles.panel} ${styles.actionPanel}`}><div className={styles.actionTitle}><RoleSymbol id={action.roleId}/><h2>{roleTitle(action.roleId,lang)}</h2></div><p>{local(action.prompt,lang)}</p>{!!action.options?.length&&<div className={styles.choiceList}>{action.options.map(option=><button key={option.id} aria-pressed={choice===option.id} className={choice===option.id?styles.chosen:""} onClick={()=>{setChoice(option.id);if(option.id==="finish")setTargets([]);}} disabled={busy}>{local(option.label,lang)}</button>)}</div>}{!!action.targets?.length&&<><p className={styles.selectionHint}>{action.min===action.max?t(`Choose ${action.min}`,`选择${action.min}个目标`):t(`Choose ${action.min} to ${action.max}`,`选择${action.min}至${action.max}个目标`)}</p><div className={styles.targetGrid}>{action.targets.map(target=><button key={target.id} disabled={busy||action.roleId==="nostradamus"&&choice==="finish"||targets.length>=action.max&&!targets.includes(target.id)&&action.max!==1} aria-pressed={targets.includes(target.id)} className={targets.includes(target.id)?styles.chosen:""} onClick={()=>toggle(target.id)}>{local(target.label,lang)}{targets.includes(target.id)&&<Check size={18}/>}</button>)}</div></>}<button className={styles.primary} disabled={busy||!valid} onClick={()=>void submit()}>{t("Confirm action", "确认行动")}<Check size={19}/></button>{action.canSkip&&<button className={styles.textButton} disabled={busy} onClick={()=>void submit(true)}>{t("Choose not to act", "选择不行动")}</button>}</section>;
}

function VotePanel({view,lang,busy,command}:{view:GameView;lang:Language;busy:boolean;command:(cmd:Command)=>Promise<boolean>}) {
  const t=(en:string,zh:string)=>lang==="en"?en:zh;
  const [target,setTarget]=useState(view.me?.vote || "");
  const submitted=!!view.me&&!view.pendingVoterIds?.includes(view.me.seatId);
  return <section className={styles.panel}><h2>{submitted?t("Your vote is in", "你已投票"):t("Who gets your vote?", "你要投给谁？")}</h2><p>{t("Choose another player. Votes stay secret until everyone has voted and the host reveals the result.", "选择另一位玩家。所有人投票后，由房主揭晓结果，之前投票保持秘密。")}</p><div className={styles.targetGrid}>{view.seats.filter(seat=>seat.id!==view.me?.seatId).map(seat=><button className={target===seat.id?styles.chosen:""} aria-pressed={target===seat.id} key={seat.id} disabled={busy} onClick={()=>setTarget(seat.id)}><b>{seat.number}</b>{seat.name}{target===seat.id&&<Check size={16}/>}</button>)}</div><button className={styles.primary} disabled={busy||!target} onClick={()=>void command({type:"vote",targetId:target,expectedPhaseId:view.phase.id})}>{submitted?t("Update my vote", "修改投票"):t("Confirm vote", "确认投票")}</button>{view.isHost&&<button className={styles.secondary} disabled={busy||!!view.pendingVoterIds?.length} onClick={()=>void command({type:"finishVote"})}>{t("Reveal the result", "揭晓结果")}</button>}</section>;
}

function People({view,lang,busy,command}:{view:GameView;lang:Language;busy:boolean;command:(cmd:Command)=>Promise<boolean>}) {
  const t=(en:string,zh:string)=>lang==="en"?en:zh;
  const [replacement,setReplacement]=useState<Record<string,string>>({});
  const [newName,setNewName]=useState("");
  const dragging=useRef<string|null>(null);
  const move=(id:string,to:number)=>{const ids=view.seats.map(seat=>seat.id);const from=ids.indexOf(id);if(from<0||to<0||to>=ids.length)return;ids.splice(from,1);ids.splice(to,0,id);void command({type:"reorderSeats",seatIds:ids});};
  return <><p>{t("Seats keep their cards and history when a replacement is approved. Replacing a bot gives its seat to the human and stops the bot. Player identities stay private.", "确认接替时，座位会保留身份与记录。接替机器人后，该座位由真人控制，机器人停止行动。玩家身份始终保密。")}</p>{view.requests?.map(request=><section className={styles.joinRequest} key={request.id}><strong>{request.name}</strong><label>{t("Replace seat", "接替座位")}<select value={replacement[request.id]||""} onChange={event=>setReplacement({...replacement,[request.id]:event.target.value})}><option value="">{t("Choose a seat", "选择座位")}</option>{view.seats.filter(seat=>seat.id!==view.me?.seatId).map(seat=><option key={seat.id} value={seat.id}>{seat.number}. {seat.name}{seat.isBot?t(" (test bot)","（测试机器人）"):seat.connected?"":t(" (offline)","（离线）")}</option>)}</select></label><div className={styles.buttonRow}><button className={styles.primary} disabled={busy||!replacement[request.id]} onClick={()=>void command({type:"approveJoin",requestId:request.id,replaceSeatId:replacement[request.id]})}>{t("Approve replacement", "确认接替")}</button><button className={styles.secondary} disabled={busy} onClick={()=>void command({type:"rejectJoin",requestId:request.id})}>{t("Decline", "拒绝")}</button></div></section>)}{view.status==="lobby"&&<p className={styles.muted}>{t("Drag seats to arrange the table, or use the arrow buttons. Seating locks once cards are dealt.","拖动座位或使用箭头调整顺序，发牌后座位锁定。")}</p>}<ul className={styles.peopleList}>{view.seats.map((seat,index)=><li key={seat.id} draggable={view.status==="lobby"&&!busy} onDragStart={()=>{dragging.current=seat.id;}} onDragOver={event=>{if(view.status==="lobby")event.preventDefault();}} onDrop={event=>{event.preventDefault();if(view.status==="lobby"&&dragging.current)move(dragging.current,index);dragging.current=null;}}><span className={styles.avatar}>{avatarGlyph(seat.photo, seat.name)}</span><div><strong>{seat.number}. {seat.name} {seat.isBot&&<OneNightBotLabel lang={lang}/>}</strong><small>{seat.isBot?t("Test bot","测试机器人"):!seat.occupied?t("Reserved seat","预留座位"):seat.connected?t("Connected","已连接"):t("Offline","离线")}</small></div><div className={styles.smallActions}>{view.status==="lobby"&&<div className={styles.seatMoves}><button aria-label={`${t("Move earlier", "前移")} ${seat.name}`} disabled={busy||index===0} onClick={()=>move(seat.id,index-1)}>↑</button><button aria-label={`${t("Move later", "后移")} ${seat.name}`} disabled={busy||index===view.seats.length-1} onClick={()=>move(seat.id,index+1)}>↓</button></div>}{seat.id!==view.me?.seatId&&<>{view.status==="lobby"&&<button className={styles.textButton} disabled={busy} onClick={()=>void command({type:"removeSeat",seatId:seat.id})}>{t("Remove","移除")}</button>}{!seat.isBot&&<button className={styles.textButton} disabled={busy||!seat.occupied} onClick={()=>void command({type:"transferHost",seatId:seat.id})}>{t("Make host","转交房主")}</button>}</>}</div></li>)}</ul>{view.status==="lobby"&&<form className={styles.form} onSubmit={async event=>{event.preventDefault();if(await command({type:"addSeat",name:newName}))setNewName("");}}><label>{t("Reserve a seat by name", "按姓名预留座位")}<input value={newName} onChange={event=>setNewName(event.target.value)} maxLength={30} required placeholder={t("Player’s name", "玩家姓名")}/></label><p className={styles.muted}>{t("The player can join using this exact name before the game starts.","游戏开始前，玩家以相同姓名加入即可入座。")}</p><button className={styles.secondary} disabled={busy||view.seats.length>=16}>{t("Add seat", "添加座位")}</button></form>}</>;
}

function Results({view,lang}:{view:GameView;lang:Language}) {
  const t=(en:string,zh:string)=>lang==="en"?en:zh;
  const result=view.result;
  if(!result)return null;
  const winners=result.winners||[];
  const votes=result.votes||{};
  return <section className={styles.results}><h2>{t("The final cards", "最终身份")}</h2><p>{winners.length?t("Winners: ","获胜玩家：")+winners.map(id=>seatLabel(view,id)).join(" · "):t("No player won this round.","本局没有玩家获胜。")}</p><div className={styles.resultGrid}>{view.seats.map(seat=>{const final=result.players.find(player=>player.seatId===seat.id);const roleId=final?.roleId||seat.roleId;const original=final?.originalRoleId;return <article key={seat.id} className={winners.includes(seat.id)?styles.winningResult:""}><div className={styles.resultTop}><strong><b>{seat.number}</b> {seat.name}</strong>{winners.includes(seat.id)&&<Crown size={22} weight="fill"/>}</div><RoleSymbol id={roleId} size={37}/><h3>{local(roleMap.get(roleId||"")?.name,lang)||roleId||t("Hidden", "未知")}</h3>{original&&original!==roleId&&<p>{t("Started as ", "初始身份：")}{local(roleMap.get(original)?.name,lang)}</p>}<p>{teamName(final?.team,lang)} · {final?.died?t("Eliminated", "出局"):t("Survived", "存活")}{final?.won?t(" · Winner", " · 获胜"):""}</p>{final?.mark&&final.mark!=="clarity"&&<p>{t("Mark: ","标记：")}{tokenName(final.mark,lang)}</p>}{final?.artifact&&<p>{t("Artifact: ","神器：")}{tokenName(final.artifact,lang)}</p>}<small>{t("Voted for: ", "投给：")}{votes[seat.id]?seatLabel(view,votes[seat.id]):t("No vote", "未投票")}<br/>{t("Votes received: ","所得票数：")}{result.counts[seat.id]||0}</small></article>;})}</div>{!!result.center?.length&&<div className={styles.finalCenter}><h3>{t("Center cards", "中央牌")}</h3>{result.center.map(card=><span key={card.id}>{Number(card.id.split(":")[1])+1}. {local(roleMap.get(card.roleId)?.name,lang)||card.roleId}</span>)}</div>}{!!result.timeline?.length&&<details className={styles.knowledge}><summary>{t("What happened overnight", "夜间行动回顾")}</summary><ol>{result.timeline.map((entry,index)=><li key={index}>{seatLabel(view,entry.seatId)} · {local(roleMap.get(entry.roleId)?.name,lang)||entry.roleId} · {tokenName(entry.type,lang)} {entry.targets?.map(id=>id.startsWith("center:")?t(`Center ${Number(id.split(":")[1])+1}`,`中央牌${Number(id.split(":")[1])+1}`):seatLabel(view,id)).join(" → ")}</li>)}</ol></details>}</section>;
}
function tokenName(value:string,lang:Language){const names:Record<string,Localized>={bowOfHunter:{en:"Bow of the Hunter",zh:"猎人之弓"},cloakOfPrince:{en:"Cloak of the Prince",zh:"王子斗篷"},swordOfBodyguard:{en:"Sword of the Bodyguard",zh:"保镖之剑"},mistOfVampire:{en:"Mist of the Vampire",zh:"吸血鬼迷雾"},alienArtifact:{en:"Alien Artifact",zh:"外星神器"},daggerOfTraitor:{en:"Dagger of the Traitor",zh:"叛徒匕首"},vampire:{en:"Vampire",zh:"吸血鬼"},fear:{en:"Fear",zh:"恐惧"},bat:{en:"Bat",zh:"蝙蝠"},disease:{en:"Disease",zh:"疾病"},love:{en:"Love",zh:"爱情"},traitor:{en:"Traitor",zh:"叛徒"},assassin:{en:"Assassin",zh:"刺客"},claw:{en:"Claw of the Werewolf",zh:"狼人之爪"},brand:{en:"Brand of the Villager",zh:"村民烙印"},cudgel:{en:"Cudgel of the Tanner",zh:"皮匠之棍"},void:{en:"Void of Nothingness",zh:"虚无之境"},mask:{en:"Mask of Muting",zh:"禁言面具"},cloak:{en:"Cloak of the Prince",zh:"王子斗篷"},sword:{en:"Sword of Courage",zh:"勇气之剑"},shroud:{en:"Shroud of Shame",zh:"羞耻之布"},view:{en:"Inspected",zh:"查看"},move:{en:"Exchanged",zh:"交换"},mark:{en:"Marked",zh:"标记"}};return names[value]?.[lang]||value;}
